components.css:
.ds-preview-button-primary { color: var(--ink); font: 1rem/1.65 system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
.ds-preview-button-primary :focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }
.ds-preview-button-primary .ds-button { display: inline-flex; align-items: center; justify-content: center; gap: 12px; min-height: 48px; border: 1px solid transparent; padding: 11px 18px; border-radius: 7px; background: var(--accent); color: var(--on-accent); text-decoration: none; font-weight: 600; font-size: .9375rem; line-height: 1.5; }
.ds-preview-button-primary .ds-button:hover { background: var(--accent-hover); text-decoration: none; }
.ds-preview-button-primary a { color: var(--accent); text-underline-offset: .2em; }
.ds-preview-button-primary a:hover { text-decoration-thickness: 2px; }
.ds-preview-button-primary svg { flex: 0 0 auto; vertical-align: middle; }
.ds-preview-button-primary h1, .ds-preview-button-primary h2, .ds-preview-button-primary h3 { line-height: 1.25; text-wrap: balance; }

.ds-preview-button-text { color: var(--ink); font: 1rem/1.65 system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
.ds-preview-button-text :focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }
.ds-preview-button-text button, .ds-preview-button-text input, .ds-preview-button-text select { font: inherit; }
.ds-preview-button-text .ds-text-button { background: none; border: 0; color: var(--accent); min-height: 44px; padding: 8px 4px; text-decoration: underline; text-underline-offset: 4px; }
.ds-preview-button-text button:disabled { cursor: default; opacity: .5; }
.ds-preview-button-text a { color: var(--accent); text-underline-offset: .2em; }
.ds-preview-button-text a:hover { text-decoration-thickness: 2px; }
.ds-preview-button-text svg { flex: 0 0 auto; vertical-align: middle; }
.ds-preview-button-text h1, .ds-preview-button-text h2, .ds-preview-button-text h3 { line-height: 1.25; text-wrap: balance; }

.ds-preview-search-field { color: var(--ink); font: 1rem/1.65 system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
.ds-preview-search-field :focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }
.ds-preview-search-field button, .ds-preview-search-field input, .ds-preview-search-field select { font: inherit; }
.ds-preview-search-field .ds-search-label { flex: 1; max-width: 610px; display: block; font-weight: 600; font-size: .875rem; }
.ds-preview-search-field .ds-search-field { display: flex; align-items: center; gap: 10px; border: 1px solid var(--line); border-radius: 7px; background: var(--surface); margin-top: 7px; padding-left: 14px; color: var(--muted); }
.ds-preview-search-field .ds-search-field:focus-within { outline: 2px solid var(--accent); outline-offset: 1px; }
.ds-preview-search-field .ds-search-field input { min-width: 0; width: 100%; border: 0; outline: none; background: transparent; padding: 12px 12px 12px 0; color: var(--ink); font-weight: 400; }
.ds-preview-search-field input::placeholder { color: var(--muted); opacity: 1; }
.ds-preview-search-field a { color: var(--accent); text-underline-offset: .2em; }
.ds-preview-search-field a:hover { text-decoration-thickness: 2px; }
.ds-preview-search-field svg { flex: 0 0 auto; vertical-align: middle; }
.ds-preview-search-field h1, .ds-preview-search-field h2, .ds-preview-search-field h3 { line-height: 1.25; text-wrap: balance; }

.ds-preview-navigation { color: var(--ink); font: 1rem/1.65 system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
.ds-preview-navigation :focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }
.ds-preview-navigation .ds-site-header { position: relative; background: var(--header); color: var(--header-ink); z-index: 20; }
.ds-preview-navigation .ds-primary-nav { display: flex; align-items: center; gap: 30px; }
.ds-preview-navigation .ds-primary-nav a { color: inherit; font-size: .9375rem; text-decoration: none; padding: 24px 0 21px; border-bottom: 3px solid transparent; }
.ds-preview-navigation .ds-primary-nav a[aria-current], .ds-preview-navigation .ds-primary-nav a:hover { border-bottom-color: #b8d8c6; }
.ds-preview-navigation a { color: var(--accent); text-underline-offset: .2em; }
.ds-preview-navigation a:hover { text-decoration-thickness: 2px; }
.ds-preview-navigation svg { flex: 0 0 auto; vertical-align: middle; }
.ds-preview-navigation h1, .ds-preview-navigation h2, .ds-preview-navigation h3 { line-height: 1.25; text-wrap: balance; }

.ds-preview-filter { color: var(--ink); font: 1rem/1.65 system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
.ds-preview-filter :focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }
.ds-preview-filter button, .ds-preview-filter input, .ds-preview-filter select { font: inherit; }
.ds-preview-filter .ds-category-filters { display: flex; flex-wrap: wrap; gap: 8px; padding: 0; border: 0; margin: 20px 0 0; }
.ds-preview-filter .ds-category-filters button { min-height: 42px; padding: 8px 16px; background: transparent; border: 1px solid var(--line); border-radius: 6px; font-size: .875rem; color: var(--muted); transition: background-color 160ms ease-out; }
.ds-preview-filter .ds-category-filters button:hover { background: var(--surface-soft); color: var(--ink); }
.ds-preview-filter .ds-category-filters button[aria-pressed='true'] { background: var(--accent); color: var(--on-accent); border-color: var(--accent); }
.ds-preview-filter a { color: var(--accent); text-underline-offset: .2em; }
.ds-preview-filter a:hover { text-decoration-thickness: 2px; }
.ds-preview-filter svg { flex: 0 0 auto; vertical-align: middle; }
.ds-preview-filter h1, .ds-preview-filter h2, .ds-preview-filter h3 { line-height: 1.25; text-wrap: balance; }
.ds-preview-filter .ds-sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }

.ds-preview-course-card { color: var(--ink); font: 1rem/1.65 system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
.ds-preview-course-card :focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }
.ds-preview-course-card .ds-course-card { grid-column: span 3; display: flex; flex-direction: column; min-width: 0; padding: 26px 28px 20px; background: var(--surface); border: 1px solid var(--line); border-radius: 12px; }
.ds-preview-course-card .ds-course-card-top { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 22px; }
.ds-preview-course-card .ds-language-mark { font: 400 1.75rem/1 var(--pixel); color: var(--accent); }
.ds-preview-course-card .ds-availability { display: inline-flex; font-size: .75rem; line-height: 1.5; font-weight: 600; padding: 4px 9px; border-radius: 4px; white-space: nowrap; }
.ds-preview-course-card .ds-availability.ds-preview { color: var(--accent); background: var(--selected); }
.ds-preview-course-card .ds-course-category { font-size: .75rem; color: var(--muted); margin-bottom: 9px; }
.ds-preview-course-card .ds-course-card h3 { font-size: 1.5rem; margin-bottom: 14px; }
.ds-preview-course-card .ds-course-card h3 a { color: var(--ink); text-decoration: none; }
.ds-preview-course-card .ds-course-card h3 a:hover { text-decoration: underline; }
.ds-preview-course-card .ds-course-card h3 span { display: block; font-size: 1rem; font-weight: 500; color: var(--muted); margin-top: 6px; }
.ds-preview-course-card .ds-course-summary { font-size: .9375rem; color: var(--muted); max-width: 51ch; margin-bottom: 24px; }
.ds-preview-course-card .ds-course-card-bottom { display: flex; justify-content: space-between; align-items: center; gap: 14px; margin-top: auto; padding-top: 16px; border-top: 1px solid var(--line); font-size: .8125rem; color: var(--muted); }
.ds-preview-course-card .ds-course-open { display: inline-flex; align-items: center; justify-content: center; min-width: 40px; min-height: 40px; border: 1px solid var(--line); border-radius: 6px; }
.ds-preview-course-card .ds-course-open:hover { background: var(--selected); }
.ds-preview-course-card a { color: var(--accent); text-underline-offset: .2em; }
.ds-preview-course-card a:hover { text-decoration-thickness: 2px; }
.ds-preview-course-card svg { flex: 0 0 auto; vertical-align: middle; }
.ds-preview-course-card h1, .ds-preview-course-card h2, .ds-preview-course-card h3 { line-height: 1.25; text-wrap: balance; }

.ds-preview-preview-notice { color: var(--ink); font: 1rem/1.65 system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
.ds-preview-preview-notice :focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }
.ds-preview-preview-notice .ds-preview-notice { display: flex; gap: 14px; align-items: start; padding: 16px 20px; color: var(--note-ink); background: var(--note); border-radius: 8px; font-size: .8125rem; }
.ds-preview-preview-notice .ds-preview-notice > svg { margin-top: 2px; }
.ds-preview-preview-notice .ds-preview-notice p { margin: 0; }
.ds-preview-preview-notice .ds-preview-notice a { flex-shrink: 0; color: inherit; margin-left: auto; }
.ds-preview-preview-notice a { color: var(--accent); text-underline-offset: .2em; }
.ds-preview-preview-notice a:hover { text-decoration-thickness: 2px; }
.ds-preview-preview-notice svg { flex: 0 0 auto; vertical-align: middle; }
.ds-preview-preview-notice h1, .ds-preview-preview-notice h2, .ds-preview-preview-notice h3 { line-height: 1.25; text-wrap: balance; }

.ds-preview-trail-position { color: var(--ink); font: 1rem/1.65 system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
.ds-preview-trail-position :focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }
.ds-preview-trail-position .ds-chapter-trail { font-size: .875rem; }
.ds-preview-trail-position .ds-chapter-trail ol { list-style: none; padding: 0; margin: 0; }
.ds-preview-trail-position .ds-chapter-trail li { display: flex; align-items: start; gap: 12px; padding: 0 0 28px; position: relative; }
.ds-preview-trail-position .ds-chapter-trail li:not(:last-child)::after { content: ''; position: absolute; left: 13px; top: 29px; bottom: 3px; width: 1px; background: var(--line); }
.ds-preview-trail-position .ds-trail-position { width: 28px; height: 28px; display: inline-flex; align-items: center; justify-content: center; background: var(--surface-soft); color: var(--muted); border-radius: 5px; flex-shrink: 0; font-size: .75rem; font-variant-numeric: tabular-nums; }
.ds-preview-trail-position .ds-chapter-trail li.ds-current .ds-trail-position { color: var(--note-ink); background: var(--note); }
.ds-preview-trail-position .ds-chapter-trail li a { text-decoration: none; color: var(--ink); font-weight: 600; line-height: 1.5; }
.ds-preview-trail-position .ds-chapter-trail li a span { display: block; color: var(--muted); font-weight: 400; font-size: .75rem; margin-top: 3px; }
.ds-preview-trail-position .ds-chapter-trail li a[aria-current] { color: var(--accent); }
.ds-preview-trail-position .ds-trail-note { font-size: .75rem; color: var(--muted); margin-top: 8px; }
.ds-preview-trail-position a { color: var(--accent); text-underline-offset: .2em; }
.ds-preview-trail-position a:hover { text-decoration-thickness: 2px; }
.ds-preview-trail-position svg { flex: 0 0 auto; vertical-align: middle; }
.ds-preview-trail-position h1, .ds-preview-trail-position h2, .ds-preview-trail-position h3 { line-height: 1.25; text-wrap: balance; }

.ds-preview-code-example { color: var(--ink); font: 1rem/1.65 system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
.ds-preview-code-example :focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }
.ds-preview-code-example .ds-code-example { margin: 24px 0 28px; background: var(--code); color: var(--code-ink); border-radius: 9px; overflow: hidden; }
.ds-preview-code-example .ds-code-example figcaption { padding: 10px 18px; color: #bdd3dc; border-bottom: 1px solid #34505b; font: .75rem/1.5 system-ui, sans-serif; }
.ds-preview-code-example .ds-code-example pre { margin: 0; padding: 20px; overflow-x: auto; font-size: .875rem; line-height: 1.8; tab-size: 2; white-space: pre; scrollbar-color: #6e929f var(--code); }
.ds-preview-code-example code { font-family: ui-monospace, 'Cascadia Code', 'SFMono-Regular', Consolas, monospace; }
.ds-preview-code-example .ds-code-example pre:focus-visible { outline-offset: -4px; }
.ds-preview-code-example a { color: var(--accent); text-underline-offset: .2em; }
.ds-preview-code-example a:hover { text-decoration-thickness: 2px; }
.ds-preview-code-example svg { flex: 0 0 auto; vertical-align: middle; }
.ds-preview-code-example h1, .ds-preview-code-example h2, .ds-preview-code-example h3 { line-height: 1.25; text-wrap: balance; }
